import sys; sys.path.insert(0,'.')
import common as C
import numpy as np

def frame_lines(name, minrun=120):
    a = C.load(name)
    dark = a.max(axis=2) < 120
    H, W = dark.shape
    vlines = []
    for x in range(W):
        col = dark[:, x]
        # longest run
        best = 0; run = 0; start=None; bestseg=(0,0)
        for y, v in enumerate(col):
            if v:
                if run == 0: start = y
                run += 1
                if run > best: best = run; bestseg=(start, y)
            else:
                run = 0
        if best >= minrun:
            vlines.append((x, bestseg, best))
    hlines = []
    for y in range(H):
        row = dark[y, :]
        best = 0; run = 0; start=None; bestseg=(0,0)
        for x, v in enumerate(row):
            if v:
                if run == 0: start = x
                run += 1
                if run > best: best = run; bestseg=(start, x)
            else:
                run = 0
        if best >= minrun:
            hlines.append((y, bestseg, best))
    print(name, \"vlines:\", vlines)
    print(name, \"hlines:\", hlines)

frame_lines(\"fig_001\")
EOF"

