/usr/bin/zsh -lc "cat > /tmp/pixcal/driver.py <<'EOF'
import sys, json
sys.path.insert(0, '/tmp/pixcal')
import common as C
import numpy as np

TASKS = {t[\"id\"]: t for t in json.load(open(f\"{C.BASE}/tasks.json\"))}

def merge_blobs(blobs, dist=25):
    used = [False]*len(blobs)
    out = []
    for i, b in enumerate(blobs):
        if used[i]: continue
        group = [b]; used[i] = True
        changed = True
        while changed:
            changed = False
            for j, o in enumerate(blobs):
                if used[j]: continue
                for g in group:
                    if abs(o[\"x\"]-g[\"x\"]) <= dist and abs(o[\"y\"]-g[\"y\"]) <= dist and np.hypot(o[\"x\"]-g[\"x\"], o[\"y\"]-g[\"y\"]) <= dist:
                        group.append(o); used[j] = True; changed = True; break
        size = sum(g[\"size\"] for g in group)
        x = sum(g[\"x\"]*g[\"size\"] for g in group)/size
        y = sum(g[\"y\"]*g[\"size\"] for g in group)/size
        out.append(dict(x=x, y=y, size=size))
    return out

def run(name, series_specs, min_orig=25, max_orig=6000, merge_dist=0):
    a = C.load(name)
    task = TASKS[name]
    res = {}
    for label, spec in series_specs.items():
        mask = spec[\"mask\"](a)
        bl = C.detect(mask, mode=spec.get(\"mode\",\"filled\"), min_orig=spec.get(\"min_orig\", min_orig), max_orig=spec.get(\"max_orig\", max_orig))
        if \"box\" in spec:
            bl = C.exclude(bl, spec[\"box\"])
        if \"keep\" in spec:
            bl = C.keep_area(bl, spec[\"keep\"])
        if \"min_size\" in spec: bl = [b for b in bl if b[\"size\"] >= spec[\"min_size\"]]
        if \"max_size\" in spec: bl = [b for b in bl if b[\"size\"] <= spec[\"max_size\"]]
        if \"min_w\" in spec: bl = [b for b in bl if b[\"w\"] >= spec[\"min_w\"]]
        if \"min_fill\" in spec: bl = [b for b in bl if b[\"fill\"] >= spec[\"min_fill\"]]
        if merge_dist and spec.get(\"merge\", merge_dist):
            bl = merge_blobs(bl, spec.get(\"merge\", merge_dist))
        xs, ys = C.series(bl, task)
        res[label] = (xs, ys)
    return res

def report(res):
    for label, (xs, ys) in res.items():
        print(f\"  {label}: n={len(xs)}\")
        for x, y in zip(xs, ys):
            print(f\"    {x:10.2f}  {y:12.4f}\")

def save(fig, res):
    import os
    p = f\"{C.BASE}/predictions.json\"
    d = {}
    if os.path.exists(p): d = json.load(open(p))
    d[fig] = [{\"label\": k, \"x\": v[0], \"y\": v[1]} for k, v in res.items()]
    with open(p, \"w\") as f:
        json.dump(d, f, indent=1)

if __name__ == \"__main__\":
    # ---------------- fig_001 ----------------
    def spec_001(a):
        LEG = (810, 1000, 20, 195)
        INSET = (305, 674, 174, 493)
        return {
            \"YA0-P\": dict(mask=lambda a: C.dark_mask(a, 100), box=(0,0,0,0), keep=None,
                          min_size=250, max_size=800, min_w=15, min_fill=0.7, merge=20),
            \"YA1\": dict(mask=lambda a: C.color_mask(a, (255,140,0), 60), merge=20),
            \"YA2\": dict(mask=lambda a: C.color_mask(a, (235,25,25), 60), merge=25),
            \"YA3\": dict(mask=lambda a: C.color_mask(a, (240,30,240), 60), merge=20),
        }
    specs = spec_001(None)
    a = C.load(\"fig_001\")
    # apply exclusions
    LEG = (810, 1000, 20, 195)
    INSET = (305, 674, 174, 493)
    for k, s in specs.items():
        if k == \"YA0-P\":
            s[\"box\"] = LEG
        else:
            s[\"box\"] = (0,0,0,0)
    res = {}
    for label, spec in specs.items():
        mask = spec[\"mask\"](a)
        bl = C.detect(mask, \"filled\")
        bl = C.exclude(bl, LEG)
        if label "'!= "YA0-P":
            bl = C.exclude(bl, INSET)
        bl = [b for b in bl if b["size"] >= (250 if label=="YA0-P" else 100) and b["size"] <= 800]
        if label == "YA0-P":
            bl = [b for b in bl if b["w"] >= 15]
        bl = merge_blobs(bl, 25)
        xs, ys = C.series(bl, TASKS["fig_001.png"])
        res[label] = (xs, ys)
    report(res)
    if "--save" in sys.argv:
        save("fig_001.png", res)
EOF
